#!/usr/bin/env node
// GENERATED by scripts/gen/build.mjs from gen/observability.rules.js - edit the sources, not this file.
const anyFile = (files, re) => files.some((f) => f.cs && re.test(f.text));
const RULES = [
  {
    id: "OBS001",
    level: "medium",
    re: /\bLog(Trace|Debug|Information|Warning|Error|Critical)\s*\(\s*\$@?"/,
    msg: "Interpolated string in a log call (loses structure, allocates when disabled)",
    fix: 'Use a message template: LogInformation("Order {OrderId} paid", id); or [LoggerMessage] source generation.',
  },
  {
    id: "OBS002",
    level: "medium",
    re: /\bLog(Error|Warning|Critical)\s*\(\s*(?!ex\b|e\b|exception\b|\w*Exception\b)[^;]*\b(ex|e|exception)\.Message\b/,
    msg: "Exception logged by message only (stack trace lost)",
    fix: 'Pass the exception first: LogError(ex, "Failed to {Action}", action);',
  },
  {
    id: "OBS003",
    level: "high",
    re: /\bLog(Trace|Debug|Information|Warning|Error|Critical)\s*\([^;]*\b(password|passwd|secret|bearer|authorization|apikey|access_token)\b/i,
    msg: "Log call mentions a credential-like value",
    fix: "Never log credentials/tokens; log ids and redact.",
  },
  {
    id: "OBS004",
    level: "low",
    re: /\bConsole\.(Write|WriteLine)\s*\(/,
    msg: "Console output instead of ILogger",
    fix: "Use ILogger<T> so output is structured, levelled and exported.",
  },
  {
    id: "OBS005",
    level: "medium",
    project: (files) => {
      const prog = files.find(
        (f) => f.cs && /WebApplication\.Create(Builder|SlimBuilder)/.test(f.text),
      );
      return prog && !anyFile(files, /MapHealthChecks|AddHealthChecks/) ? [{ file: prog.rel }] : [];
    },
    msg: "No health checks (orchestrators cannot tell live from ready)",
    fix: 'AddHealthChecks(); MapHealthChecks("/health/live", predicate: _ => false) and a /health/ready that runs tagged dependency checks.',
  },
  {
    id: "OBS006",
    level: "low",
    project: (files) => {
      const prog = files.find(
        (f) => f.cs && /WebApplication\.Create(Builder|SlimBuilder)/.test(f.text),
      );
      return prog &&
        !anyFile(
          files,
          /AddOpenTelemetry|ConfigureOpenTelemetry|UseOtlpExporter|AddOtlpExporter|AddApplicationInsights|UseSerilog/,
        )
        ? [{ file: prog.rel }]
        : [];
    },
    msg: "No telemetry pipeline configured (OpenTelemetry/Serilog/App Insights)",
    fix: "Add OpenTelemetry traces + metrics + logs with an OTLP exporter (or the Aspire ServiceDefaults pattern).",
  },
  {
    id: "OBS008",
    level: "medium",
    re: /new\s+Meter\s*\(|new\s+ActivitySource\s*\(/,
    msg: "Meter/ActivitySource created by hand",
    fix: "Inject IMeterFactory for Meters (DI-scoped, testable); register the ActivitySource name with OpenTelemetry (AddSource).",
  },
];

// Heuristic, regex-based scan of a .NET repo (.cs and appsettings*.json). It finds candidates, not proof:
// read every hit in context before changing code. Skips bin/obj/node_modules/.git; scans production code (test projects are skipped).
// Usage: node <this-file> [path] [--json] [--strict]    (--strict: exit 1 when any HIGH finding exists)
import { readdirSync, readFileSync } from "node:fs";
import { join, relative } from "node:path";

const args = process.argv.slice(2);
const root = args.find((a) => !a.startsWith("--")) ?? process.cwd();
const SCOPE = "code";
const SKIP = new Set(["bin", "obj", "node_modules", ".git", ".vs", "TestResults"]);
const isTest = (rel) => /(^|[\\/])[^\\/]*\.?tests?([\\/]|\.)/i.test(rel);

function* walk(dir) {
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    if (e.isDirectory()) {
      if (!SKIP.has(e.name)) yield* walk(join(dir, e.name));
    } else if (/\.cs$|(^|[\\/])appsettings[^\\/]*\.json$/i.test(e.name)) yield join(dir, e.name);
  }
}
const lineOf = (text, index) => text.slice(0, index).split("\n").length;

const files = [];
for (const abs of walk(root)) {
  const rel = relative(root, abs).split("\\").join("/");
  if (SCOPE === "tests" ? isTest(rel) : !isTest(rel))
    files.push({ rel, text: readFileSync(abs, "utf8"), cs: abs.endsWith(".cs") });
}

const findings = [];
const add = (r, file, line) =>
  findings.push({ id: r.id, level: r.level, file, line, msg: r.msg, fix: r.fix });
for (const r of RULES) {
  if (r.project) {
    for (const hit of r.project(files)) add(r, hit.file, hit.line ?? 1);
    continue;
  }
  for (const f of files) {
    if (r.json ? f.cs : !f.cs) continue;
    if (r.re) {
      f.text.split("\n").forEach((l, i) => {
        if (f.cs && l.trimStart().startsWith("//")) return;
        if (r.re.test(l)) add(r, f.rel, i + 1);
      });
    } else if (r.multi) {
      for (const m of f.text.matchAll(r.multi)) add(r, f.rel, lineOf(f.text, m.index));
    } else if (r.fn) {
      for (const line of r.fn(f.text, f.rel)) add(r, f.rel, line);
    }
  }
}

const order = { high: 0, medium: 1, low: 2 };
findings.sort(
  (a, b) => order[a.level] - order[b.level] || a.file.localeCompare(b.file) || a.line - b.line,
);
if (args.includes("--json")) console.log(JSON.stringify(findings, null, 2));
else {
  for (const f of findings)
    console.log(
      `${f.file}:${f.line}  ${f.level.toUpperCase()}  ${f.id}  ${f.msg}\n    fix: ${f.fix}`,
    );
  const n = (l) => findings.filter((f) => f.level === l).length;
  console.log(
    `\n${files.length} files scanned: ${n("high")} high, ${n("medium")} medium, ${n("low")} low.`,
  );
}
if (args.includes("--strict") && findings.some((f) => f.level === "high")) process.exit(1);
